MM.mnemo[29] = {"cards":[{"id":"ko-k3-0474","w":"낫다","cs":"uzdravit se; být lepší","en":"to heal, to recover","p":"v","o":"k","ex":"감기 다 나았어요?","exc":"Už ses úplně uzdravil z nachlazení?","m":"Nepravidelné ㅅ: 나아요, 나았어요. 감기가 낫다 = vyléčit se z nachlazení. Jako přídavné jméno „lepší“: 이게 더 나아요.","tv":["나아요","나았어요","나을 거예요"],"irr":"ㅅ"},{"id":"ko-k3-0475","w":"젓다","cs":"míchat; zamíchat (tekutinu, těsto)","en":"to stir (liquid)","p":"v","o":"k","ex":"잘 저으세요.","exc":"Dobře to zamíchejte.","m":"Nepravidelné časování s ㅅ: před samohláskou ㅅ vypadne (ale slabiky se nespojí) → 저어요 (míchá), 저었어요 (zamíchal), 저으세요 (zamíchejte). Vazba: 커피를 젓다 = zamíchat kávu.","tv":["저어요","저었어요","저을 거예요"],"irr":"ㅅ"},{"id":"ko-k3-0476","w":"잇다","cs":"spojit; propojit; navázat","en":"to connect, to link","p":"v","o":"k","ex":"두 개를 이었어요.","exc":"Spojil jsem ty dvě věci dohromady. (를 → 4. pád)","m":"Nepravidelné časování s ㅅ: před samohláskou ㅅ mizí → 이어요 (spojuje), 이었어요 (spojil). Vazba: 두 개를 잇다 = spojit dvě věci.","tv":["이어요","이었어요","이을 거예요"],"irr":"ㅅ"},{"id":"ko-k3-0477","w":"짓다","cs":"postavit (dům); uvařit (rýži); vymyslet (jméno); složit (báseň)","en":"to make, to build, to compose","p":"v","o":"k","ex":"이 집을 누가 지었어요?","exc":"Kdo postavil tenhle dům? (을 → 4. pád; 가 → 1. pád)","m":"Nepravidelné časování s ㅅ → 지어요 (staví / tvoří), 지었어요 (postavil). Používá se pro ‚vytvoření‘ důležitých věcí: 집을 짓다 (postavit dům), 밥을 짓다 (uvařit rýži), 이름을 짓다 (dát/vymyslet jméno).","tv":["지어요","지었어요","지을 거예요"],"irr":"ㅅ"},{"id":"ko-k3-0478","w":"긋다","cs":"nakreslit čáru; udělat tah; škrtnout","en":"to draw (a line)","p":"v","o":"k","ex":"그 문장에 밑줄 그었어요.","exc":"Podtrhl jsem tu větu. (에 → kde)","m":"Nepravidelné časování s ㅅ → 그어요 (kreslí čáru), 그었어요 (nakreslil čáru). Nejčastější vazby: 선을 긋다 (nakreslit čáru), 밑줄을 긋다 (podtrhnout).","tv":["그어요","그었어요","그을 거예요"],"irr":"ㅅ"},{"id":"ko-k3-0479","w":"붓다","cs":"nalít, zalít (vodou)","en":"to pour","p":"v","o":"k","ex":"쌀을 씻기 위해서 물을 부으세요.","exc":"Abys rýži propláchl, nalij do ní vodu. (을 → 4. pád; -기 위해서 → aby)","m":"Nepravidelné ㅅ: 부어요, 부었어요, 부으세요. 물을 붓다 = nalít vodu. Stejně znějící 붓다 = otéct (얼굴이 부었어요).","tv":["부어요","부었어요","부을 거예요"],"irr":"ㅅ"},{"id":"ko-k3-0480","w":"벗다","cs":"svléknout, zout, sundat","en":"to take (clothes) off","p":"v","o":"k","ex":"신발을 벗어 주세요.","exc":"Zujte si prosím boty. (을 → 4. pád; -어 주세요 → prosba)","m":"Pravidelné ㅅ: 벗어요. Jedno sloveso na sundání všeho; oblékání má zvlášť 입다 (oblečení), 신다 (boty), 쓰다 (čepice, brýle).","tv":["벗어요","벗었어요","벗을 거예요"]},{"id":"ko-k3-0481","w":"감기","cs":"nachlazení; rýma","en":"(a) cold","p":"n","o":"s","ex":"감기 다 나았어요?","exc":"Už ses úplně vyléčil z toho nachlazení?","m":"感 pocit, cítit + 氣 energie, vzduch = ‚chycení chladného vzduchu‘, tedy nachlazení. Časté vazby: 감기에 걸리다 (nastydnout, chytit rýmu), 감기가 낫다 (uzdravit se z nachlazení).","r":["gam-感","gi-氣"]},{"id":"ko-k3-0483","w":"쌀","cs":"rýže (syrová, nevařená); zrnka rýže","en":"(uncooked) rice","p":"n","o":"k","ex":"먼저 쌀을 씻어야 돼요.","exc":"Nejprve je potřeba propláchnout rýži. (을 → 4. pád)","m":"Označuje syrovou, ještě neuvařenou rýži (na rozdíl od vařené rýže a jídla 밥). Častá vazba: 쌀을 씻다 = propláchnout rýži před vařením."},{"id":"ko-k3-0484","w":"밑줄","cs":"podtržení; podtrhávací čára","en":"underline","p":"n","o":"k","ex":"그 문장에 밑줄 그었어요.","exc":"Podtrhl jsem tu větu. (에 → kde)","m":"밑 (spodek, dole) + 줄 (čára, linka) = čára dole pod textem, tedy podtržení. Vazba: 밑줄을 긋다 = podtrhnout."}],"gram":{"id":"ko-k3-g29","w":"ㅅ 불규칙","en":"Irregulars: ㅅ","cs":"nepravidelná slovesa a přídavná jména na ㅅ","vy":"U skupiny nepravidelných sloves a přídavných jmen končících na ㅅ (např. 낫다, 젓다, 잇다, 짓다, 붓다, 긋다) koncové ㅅ vypadává, jakmile za ním následuje koncovka začínající samohláskou (např. -아요/어요, -(으)세요, -(으)면, -(으)ㄹ 거예요). Po vypadnutí ㅅ se sousední samohlásky nikdy nestahují dohromady (낫 + 아요 → 나아요, 짓 + 어요 → 지어요). Před koncovkou začínající souhláskou (např. -고, -는) zůstává ㅅ beze změny.","m":"Po vypadnutí ㅅ se samohlásky nespojují do jedné slabiky: 낫다 → 나아요 (nikoli 나요), 짓다 → 지어요 (nikoli 져요). Běžná slovesa jako 웃다 (smát se), 씻다 (mýt se) nebo 벗다 (svlékat si) jsou pravidelná a ㅅ si zachovávají (웃어요, 씻어요).","s":[["낫 + 아요 → 나아요","Je to lepší. / Uzdravuje se to. (před samohláskou ㅅ vypadává)"],["젓 + 어요 → 저어요","Míchám. / Zamíchej to prosím."],["잇 + 었어요 → 이었어요","Spojil jsem to. / Propojil jsem to."],["짓 + 었어요 → 지었어요","Postavil jsem to. / Vymyslel jsem (jméno)."],["잘 저으세요.","Dobře to promíchejte."],["두 개를 이었어요.","Spojil jsem ty dvě věci k sobě."],["이 집을 누가 지었어요?","Kdo postavil tenhle dům?"],["좋은 이름을 지을 거예요.","Vymyslím nějaké pěkné jméno."],["감기 다 나았어요?","Už ses úplně uzdravil z nachlazení?"],["웃어요. · 씻을 거예요. · 신발을 벗어 주세요.","Usmívám se. · Umyju se. · Zujte si prosím boty. (pravidelná slovesa: ㅅ zůstává)"],["강아지 이름이 뭐예요? — 코코예요.","Jak se jmenuje vaše štěně? — Jmenuje se Koko."],["누가 지었어요? — 제가 지었어요.","Kdo to jméno vymyslel? — Já jsem ho vymyslel."],["짓다 → 지어요 · 지었어요 · 지을 거예요 · 짓고 있어요","stavět / tvořit / vařit rýži (짓다) → stavím · stavěl jsem · budu stavět · právě stavím"],["밥 짓는 것은 전혀 어렵지 않아요.","Uvařit rýži není vůbec těžké."],["물을 부은 다음에 손으로 저으세요.","Poté, co nalijete vodu, zamíchejte to rukou."],["그 문장에 밑줄 그었어요.","Podtrhl jsem tu větu."]]}};
